import { BUILDINGS } from '../data/buildingData';
import Position from '../../../b13/ecs/components/Position';
import Building from '../components/Building';

const IMPASSABLE_SLOTS = new Set(['eau', 'glace', 'montagne']);

// ─────────────────────────────────────────────────────────────
// CommunityDecisionSystem
//
// Chaque tick, pour chaque village :
//   1. Dérive les communityNeeds depuis les bâtiments construits
//      (data-driven via BUILDINGS[].needContribution)
//   2. Si pas de plan → choisit le bâtiment le plus urgent
//      (besoin le plus bas parmi les triggers non satisfaits)
//   3. Calcule les ressources manquantes → gatherOrder
//   4. Si stockpile complet → construit (consomme ressources)
// ─────────────────────────────────────────────────────────────

// Needs que le village possède (correspond aux clés de Village.communityNeeds)
const ALL_NEEDS = ['shelter', 'food_security', 'community', 'knowledge', 'culture', 'commerce','defense'];

export default class CommunityDecisionSystem {
  update({ em, grid }) {
    for (const vid of em.query('Village')) {
      const v = em.getComponent(vid, 'Village');

      // ── 1. Bases dynamiques issues des habitants ─────────────
      const needs = {};
      for (const n of ALL_NEEDS) needs[n] = 0;

      const members = em.query('Inhabitant', 'Group', 'Needs')
        .filter(id => em.getComponent(id, 'Group').groupId === v.groupId);
      const memberCount = members.length;

      if (memberCount > 0) {
        const avgSocial = members.reduce((s, id) => s + (em.getComponent(id, 'Needs').social ?? 0), 0) / memberCount;
        const avgFoi    = members.reduce((s, id) => s + (em.getComponent(id, 'Needs').foi    ?? 0), 0) / memberCount;
        // community ∝ social moyen   (social bas → community bas → déclenche bâtiments)
        needs.community = avgSocial * 0.5;       // 0..50 base
        // culture ∝ foi moyenne       (foi basse → culture basse → déclenche lieux de culte)
        needs.culture   = avgFoi    * 0.5;       // 0..50 base
      }

      // food_security : ratio stockpile / habitants
      needs.food_security = Math.min(30,
        (v.stockpile.nourriture / Math.max(1, memberCount)) * 5
      );

      // commerce : croît avec l'argent du village (0 argent = besoin non satisfait)
      needs.commerce = Math.min(40, (v.stockpile.argent ?? 0) * 1.5);

      // ── 2. Contributions des bâtiments (sauf knowledge) ─────
      let knowledgeBldContrib = 0;
      for (const bld of BUILDINGS) {
        const count = v.buildings[bld.id] ?? 0;
        if (count === 0) continue;
        for (const [need, value] of Object.entries(bld.needContribution ?? {})) {
          if (need === 'knowledge') { knowledgeBldContrib += count * value; continue; }
          needs[need] = Math.min(100, (needs[need] ?? 0) + count * value);
        }
      }

      // ── 3. Knowledge : croît quand les autres besoins sont satisfaits
      // (avgPrimary > 40 → knowledge commence à croître, seul levier : bâtiments de savoir)
      const avgPrimary = (needs.shelter + needs.food_security + needs.community + needs.culture) / 4;
      needs.knowledge  = Math.min(100, Math.max(0, avgPrimary * 0.5 - 20) + knowledgeBldContrib);

      // ── 4. Production des bâtiments → stockpile ─────────────
      // (0.05 par tick ≈ 1 unité toutes les ~20 ticks)
      const NON_RESOURCES = new Set(['warrior', 'archer', 'canon']);
      for (const bld of BUILDINGS) {
        const count = v.buildings[bld.id] ?? 0;
        if (count === 0 || !bld.produces) continue;
        for (const [resource, amount] of Object.entries(bld.produces)) {
          if (NON_RESOURCES.has(resource)) continue;
          v.stockpile[resource] = (v.stockpile[resource] ?? 0) + count * amount * 0.05;
        }
      }

      v.communityNeeds = needs;

      // ── 2. Choisit un plan si aucun en cours ────────────────
      if (!v.currentPlan) {
        v.currentPlan = this._pickPlan(v);
      }

      // ── 3. Calcule les ressources manquantes ─────────────────
      if (v.currentPlan) {
        const missing = {};
        for (const [res, needed] of Object.entries(v.currentPlan.cost)) {
          const diff = needed - (v.stockpile[res] ?? 0);
          if (diff > 0) missing[res] = diff;
        }
        v.currentPlan.missing = missing;

        const missingKeys = Object.keys(missing);
        if (missingKeys.length > 0) {
          v.gatherOrder = missingKeys[0];
        } else {
          // ── 4. Stockpile OK → on construit ──────────────────
          v.gatherOrder = null;
          this._executeBuild(v, vid, em, grid);
        }
      } else {
        v.gatherOrder = null;
      }

      em.addComponent(vid, 'Village', v);
    }
  }

  // Choisit le bâtiment à construire :
  // - triggers non satisfaits
  // - prérequis remplis
  // - quota non atteint
  // → priorité au besoin le plus bas (urgence max)
  _pickPlan(v) {
    let bestScore = Infinity;
    let bestBld   = null;

    for (const bld of BUILDINGS) {
      const { need } = bld.trigger;
      const current = v.communityNeeds[need] ?? 0;

      // Quota atteint → inutile d'en construire un de plus
      if ((v.buildings[bld.id] ?? 0) >= bld.maxPerVillage) continue;

      // Prérequis non satisfaits → pas encore disponible
      if (bld.requires) {
        const ok = Object.entries(bld.requires)
          .every(([req, n]) => (v.buildings[req] ?? 0) >= n);
        if (!ok) continue;
      }

      // Ce bâtiment apporterait-il un gain réel ?
      // On ne construit pas si le need dépasse déjà ce que ce bâtiment contribue.
      const contribution = bld.needContribution?.[need] ?? 0;
      if (current >= 100 - contribution) continue; // gain marginal nul

      // Priorité au need le plus bas (le plus urgent)
      if (current < bestScore) { bestScore = current; bestBld = bld; }
    }

    if (!bestBld) return null;
    return { buildingId: bestBld.id, label: bestBld.label, cost: { ...bestBld.cost }, missing: {} };
  }

  _executeBuild(v, vid, em, grid) {
    const bld = BUILDINGS.find(b => b.id === v.currentPlan.buildingId);
    if (!bld) { v.currentPlan = null; return; }

    for (const [res, amount] of Object.entries(bld.cost)) {
      v.stockpile[res] = Math.max(0, (v.stockpile[res] ?? 0) - amount);
    }
    v.buildings[bld.id] = (v.buildings[bld.id] ?? 0) + 1;
    v.currentPlan = null;

    // ── Spawn entité bâtiment sur la map ─────────────────────
    const vpos = em.getComponent(vid, 'Position');
    if (vpos && grid) {
      const slot = this._findBuildingSlot(vpos, bld.id, em, grid);
      if (slot) {
        const eid = em.createEntity();
        em.addComponent(eid, 'Position', Position(slot.x, slot.y));
        em.addComponent(eid, 'Building', Building(bld.id, bld.label, v.groupId));
      }
    }
  }

  // Cherche une cellule libre en spirale autour du centre du village.
  // place_centrale → centre exact ; autres → rayon croissant en évitant le centre.
  _findBuildingSlot(vpos, bldId, em, grid) {
    if (bldId === 'place_centrale') return { x: vpos.x, y: vpos.y };

    const occupied = new Set(
      em.query('Position', 'Building').map(id => {
        const p = em.getComponent(id, 'Position');
        return `${p.x},${p.y}`;
      })
    );
    occupied.add(`${vpos.x},${vpos.y}`); // centre réservé à place_centrale

    for (let r = 1; r <= 12; r++) {
      for (let dx = -r; dx <= r; dx++) {
        for (let dy = -r; dy <= r; dy++) {
          if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue; // bord du carré seulement
          const x = vpos.x + dx;
          const y = vpos.y + dy;
          if (x < 0 || y < 0 || x >= grid.cols || y >= grid.rows) continue;
          if (occupied.has(`${x},${y}`)) continue;
          const cell = grid.getCell(x, y);
          if (!cell || IMPASSABLE_SLOTS.has(cell.terrainType)) continue;
          return { x, y };
        }
      }
    }
    return null;
  }
}
