import { Box, Button, ButtonGroup, Chip, Divider, LinearProgress, MenuItem, Select, Slider, Tab, Tabs, Typography } from "@mui/material";
import { useState } from "react";
import { useWB } from "../WBContext";
import WBCalibrator from "./WBCalibrator";
import WBCanvas from "./WBCanvas";

const BOTTOM_H = 220;

// ── Panels ────────────────────────────────────────────────────

function StatsPanel() {
  const { tick, grid, engineRef } = useWB();
  const em = engineRef.current?.em;

  let plantCount = 0, mineralCount = 0, humanCount = 0, byType = {};
  if (em) {
    const ids = em.query('Position', 'Resource', 'Species');
    for (const id of ids) {
      const sp  = em.getComponent(id, 'Species');
      const res = em.getComponent(id, 'Resource');
      if (sp.type === 'plant')   plantCount++;
      if (sp.type === 'mineral') mineralCount++;
      byType[res.type] = (byType[res.type] ?? 0) + 1;
    }
    humanCount = em.query('Inhabitant').length;
  }

  return (
    <Box sx={{ display: 'flex', gap: 4, flexWrap: 'wrap', p: 1 }}>
      <Box>
        <Typography variant="caption" color="text.secondary">Tick</Typography>
        <Typography variant="h6">{tick}</Typography>
      </Box>
      <Box>
        <Typography variant="caption" color="text.secondary">Habitants</Typography>
        <Typography variant="h6">{humanCount}</Typography>
      </Box>
      <Box>
        <Typography variant="caption" color="text.secondary">Plantes</Typography>
        <Typography variant="h6">{plantCount}</Typography>
      </Box>
      <Box>
        <Typography variant="caption" color="text.secondary">Minéraux</Typography>
        <Typography variant="h6">{mineralCount}</Typography>
      </Box>
      <Divider orientation="vertical" flexItem />
      <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', alignItems: 'flex-end' }}>
        {Object.entries(byType)
          .sort((a, b) => b[1] - a[1])
          .slice(0, 12)
          .map(([type, count]) => (
            <Box key={type} sx={{ textAlign: 'center' }}>
              <Typography variant="caption" display="block" color="text.secondary">{type}</Typography>
              <Typography variant="body2">{count}</Typography>
            </Box>
          ))
        }
      </Box>
    </Box>
  );
}

function CommandesPanel() {
  const { isRunning, toggleRun, speed, setSpeed, seaLevel, setSeaLevel,
          cellSize, setCellSize, generateNewWorld,
          saveGame, loadSave, clearSave, hasSave, tick } = useWB();

  return (
    <Box sx={{ display: 'flex', gap: 4, flexWrap: 'wrap', alignItems: 'center', p: 1 }}>
      {/* Play / Pause */}
      <Button
        variant="contained"
        size="small"
        onClick={toggleRun}
        color={isRunning ? 'warning' : 'success'}
      >
        {isRunning ? '⏸ Pause' : '▶ Play'}
      </Button>

      {/* Vitesse */}
      <Box sx={{ minWidth: 130 }}>
        <Typography variant="caption" color="text.secondary">Vitesse</Typography>
        <ButtonGroup size="small" variant="outlined">
          {[1, 2, 3].map(v => (
            <Button
              key={v}
              variant={speed === v ? 'contained' : 'outlined'}
              onClick={() => setSpeed(v)}
            >
              {v === 1 ? '🐢' : v === 2 ? '🐇' : '⚡'}
            </Button>
          ))}
        </ButtonGroup>
      </Box>

      {/* Niveau de la mer */}
      <Box sx={{ minWidth: 150 }}>
        <Typography variant="caption" color="text.secondary">
          Mer : {seaLevel}
        </Typography>
        <Slider
          size="small"
          min={5} max={60} step={1}
          value={seaLevel}
          onChange={(_, v) => setSeaLevel(v)}
        />
      </Box>

      {/* Taille cellule */}
      <Box sx={{ minWidth: 150 }}>
        <Typography variant="caption" color="text.secondary">
          Zoom : {cellSize}px
        </Typography>
        <Slider
          size="small"
          min={6} max={48} step={2}
          value={cellSize}
          onChange={(_, v) => setCellSize(v)}
        />
      </Box>

      {/* Nouveau monde */}
      <Button variant="outlined" size="small" color="secondary" onClick={generateNewWorld}>
        🌍 Nouveau monde
      </Button>

      {/* Save / Load */}
      <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
        <Button variant="outlined" size="small" color="success" onClick={saveGame}>
          💾 Sauvegarder
        </Button>
        <Button variant="outlined" size="small" disabled={!hasSave} onClick={loadSave}>
          📂 Charger
        </Button>
        {hasSave && (
          <Typography variant="caption" color="text.secondary" sx={{ cursor: 'pointer', textDecoration: 'underline' }}
            onClick={clearSave}>
            ✕ effacer
          </Typography>
        )}
      </Box>
      {hasSave && (
        <Typography variant="caption" color="success.main">
          💾 auto-save actif (tick {tick - (tick % 50)})
        </Typography>
      )}
    </Box>
  );
}

function NeedBar({ label, value, color }) {
  return (
    <Box sx={{ minWidth: 110 }}>
      <Typography variant="caption" color="text.secondary">{label} {Math.round(value)}</Typography>
      <LinearProgress
        variant="determinate"
        value={value}
        sx={{ height: 6, borderRadius: 1, bgcolor: 'grey.800',
              '& .MuiLinearProgress-bar': { bgcolor: color } }}
      />
    </Box>
  );
}

function VillageInfo({ vid, em }) {
  if (!vid || !em) return null;
  const pos     = em.getComponent(vid, 'Position');
  const village = em.getComponent(vid, 'Village');
  if (!village) return null;
  const { stockpile, buildings, communityNeeds, currentPlan, gatherOrder } = village;
  const members = em.query('Inhabitant', 'Group').filter(id => em.getComponent(id, 'Group').groupId === village.groupId);

  return (
    <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', p: 1, alignItems: 'flex-start' }}>
      <Box sx={{ minWidth: 110 }}>
        <Typography variant="caption" color="text.secondary">{village.groupId}</Typography>
        {pos && <Typography variant="body2">({pos.x}, {pos.y})</Typography>}
        <Typography variant="body2" color="text.secondary">{members.length} habitant(s)</Typography>
        <Box sx={{ mt: 0.5, display: 'flex', flexDirection: 'column', gap: 0.5 }}>
          {currentPlan && (
            <Chip size="small" color="warning"
              label={`🔨 ${currentPlan.label ?? currentPlan.buildingId} — ${Object.keys(currentPlan.missing ?? {}).length === 0 ? '✓ prêt' : Object.entries(currentPlan.missing).map(([r,n])=>`${n} ${r}`).join(', ')}`}
            />
          )}
          {gatherOrder && <Chip size="small" color="info" label={`📦 Collecte: ${gatherOrder}`} />}
          {!currentPlan && !gatherOrder && <Chip size="small" label="😌 Stable" />}
        </Box>
      </Box>

      {/* Stockpile */}
      <Box sx={{ minWidth: 110 }}>
        <Typography variant="caption" color="text.secondary">Stockpile</Typography>
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mt: 0.5 }}>
          {Object.entries(stockpile).filter(([,v]) => v > 0).map(([k, v]) => (
            <Chip key={k} size="small" label={`${k}: ${Math.floor(v)}`} variant="outlined" />
          ))}
          {Object.values(stockpile).every(v => v === 0) &&
            <Typography variant="body2" color="text.secondary">vide</Typography>}
        </Box>
      </Box>

      {/* Bâtiments */}
      <Box sx={{ minWidth: 110 }}>
        <Typography variant="caption" color="text.secondary">Bâtiments</Typography>
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mt: 0.5 }}>
          {Object.entries(buildings).map(([k, v]) => (
            <Chip key={k} size="small" color="success" label={`${k} ×${v}`} />
          ))}
          {Object.keys(buildings).length === 0 &&
            <Typography variant="body2" color="text.secondary">aucun</Typography>}
        </Box>
      </Box>

      {/* Besoins communautaires */}
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.8, minWidth: 130 }}>
        <NeedBar label="Abri"         value={communityNeeds.shelter       ?? 0} color="#90caf9" />
        <NeedBar label="Nourriture"   value={communityNeeds.food_security ?? 0} color="#a5d6a7" />
        <NeedBar label="Communauté"   value={communityNeeds.community     ?? 0} color="#ffcc80" />
        <NeedBar label="Connaissance" value={communityNeeds.knowledge     ?? 0} color="#ce93d8" />
        <NeedBar label="Culture"      value={communityNeeds.culture       ?? 0} color="#f48fb1" />
        <NeedBar label="Commerce"     value={communityNeeds.commerce      ?? 0} color="#80cbc4" />
        <NeedBar label="Defense"     value={communityNeeds.defense      ?? 0} color="#ed4609" />
      </Box>
    </Box>
  );
}

function VillagePanel() {
  const { tick, engineRef } = useWB();
  const em = engineRef.current?.em;
  const [selectedVid, setSelectedVid] = useState(null);

  if (!em) return null;
  const vids = em.query('Village');
  if (vids.length === 0) return <Box sx={{ p: 1 }}><Typography variant="body2" color="text.secondary">Aucun village.</Typography></Box>;

  const vid = selectedVid ?? vids[0];

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <Box sx={{ px: 1, pt: 0.5 }}>
        <Select
          size="small"
          value={vid}
          onChange={e => setSelectedVid(e.target.value)}
          sx={{ fontSize: 12, minWidth: 160 }}
        >
          {vids.map(id => {
            const v = em.getComponent(id, 'Village');
            const pos = em.getComponent(id, 'Position');
            const members = em.query('Inhabitant', 'Group').filter(mid => em.getComponent(mid, 'Group').groupId === v?.groupId).length;
            return (
              <MenuItem key={id} value={id}>
                {v?.groupId} — ({pos?.x},{pos?.y}) · {members} hab.
              </MenuItem>
            );
          })}
        </Select>
      </Box>
      <Box sx={{ flex: 1, overflow: 'auto' }}>
        <VillageInfo vid={vid} em={em} key={`${vid}-${tick}`} />
      </Box>
    </Box>
  );
}

function SelectionPanel() {
  const { selected, engineRef } = useWB();
  const em = engineRef.current?.em;

  if (selected === null || !em) {
    return (
      <Box sx={{ p: 1 }}>
        <Typography variant="body2" color="text.secondary">
          Cliquez sur un habitant, un village ou une ressource.
        </Typography>
      </Box>
    );
  }

  const pos      = em.getComponent(selected, 'Position');
  const species  = em.getComponent(selected, 'Species');
  const res      = em.getComponent(selected, 'Resource');
  const age      = em.getComponent(selected, 'Age');
  const stats    = em.getComponent(selected, 'Stats');
  const needs    = em.getComponent(selected, 'Needs');
  const state    = em.getComponent(selected, 'State');
  const group    = em.getComponent(selected, 'Group');
  const village  = em.getComponent(selected, 'Village');
  const building = em.getComponent(selected, 'Building');

  // ── Vue village ─────────────────────────────────────────────
  if (village) {
    return <VillageInfo vid={selected} em={em} />;
  }

  // ── Vue bâtiment ─────────────────────────────────────────────
  if (building) {
    return (
      <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', p: 1, alignItems: 'flex-start' }}>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
          <Chip label={building.label ?? building.type} size="small" color="success" />
          <Chip label={`🏘 ${building.groupId}`} size="small" variant="outlined" />
          {pos && <Typography variant="caption" color="text.secondary">({pos.x}, {pos.y})</Typography>}
        </Box>
      </Box>
    );
  }

  // ── Vue habitant ────────────────────────────────────────────
  if (group) {
    const stateLabel = state
      ? `${state.current}${state.task?.action ? ` › ${state.task.action}` : ''}`
      : '—';
    return (
      <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', p: 1, alignItems: 'flex-start' }}>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, minWidth: 110 }}>
          <Chip
            label={group.role === 'chief' ? '👑 Chef' : group.role}
            size="small"
            color={group.role === 'chief' ? 'warning' : 'default'}
          />
          <Chip label={`Groupe ${group.groupId}`} size="small" variant="outlined" />
          <Chip label={stateLabel} size="small" color="info" variant="outlined" />
          {pos && <Typography variant="caption" color="text.secondary">({pos.x}, {pos.y})</Typography>}
          {age && <Typography variant="caption" color="text.secondary">Âge {age.age}/{age.maxAge}</Typography>}
          {state?.target && (
            <Typography variant="caption" color="text.secondary">
              → ({state.target.x}, {state.target.y})
            </Typography>
          )}
        </Box>

        {needs && (
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.8, minWidth: 120 }}>
            <Typography variant="caption" color="text.secondary">Besoins</Typography>
            <NeedBar label="Faim"    value={needs.hunger} color="#ff9800" />
            <NeedBar label="Énergie" value={needs.energy} color="#66bb6a" />
            <NeedBar label="Social"  value={needs.social} color="#42a5f5" />
            <NeedBar label="Foi"     value={needs.foi    ?? 0} color="#ffcc80" />
          </Box>
        )}

        {stats && (
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.8, minWidth: 120 }}>
            <Typography variant="caption" color="text.secondary">Stats</Typography>
            <NeedBar label="Force"        value={stats.force}        color="#ef5350" />
            <NeedBar label="Intelligence" value={stats.intelligence} color="#ab47bc" />
            <NeedBar label="Charme"       value={stats.charme}       color="#ec407a" />
            <NeedBar label="Perception"   value={stats.perception}   color="#26c6da" />
          </Box>
        )}
      </Box>
    );
  }

  // ── Vue ressource ────────────────────────────────────────────
  return (
    <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', p: 1, alignItems: 'flex-start' }}>
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
        {species && <Chip label={species.type} size="small" />}
        {res     && <Chip label={res.type} size="small" color="primary" variant="outlined" />}
        {pos     && <Typography variant="caption" color="text.secondary">({pos.x}, {pos.y})</Typography>}
        {age     && <Typography variant="caption" color="text.secondary">Âge {age.age}/{age.maxAge}</Typography>}
      </Box>
    </Box>
  );
}

// ── Layout principal ──────────────────────────────────────────

export function WBInner() {
  const [tab, setTab] = useState(0);
  const calibrating = tab === 4;

  return (
    <Box sx={{ height: '100dvh', display: 'flex', flexDirection: 'column', bgcolor: '#111' }}>

      {!calibrating && (
        <Box sx={{ flex: 1, overflow: 'auto' }}>
          <WBCanvas />
        </Box>
      )}

      {calibrating && (
        <Box sx={{ flex: 1, overflow: 'hidden' }}>
          <WBCalibrator />
        </Box>
      )}

      <Box sx={{
        height: calibrating ? 36 : BOTTOM_H,
        display: 'flex',
        flexDirection: 'column',
        borderTop: '1px solid',
        borderColor: 'divider',
        bgcolor: 'background.paper',
      }}>
        <Tabs
          value={tab}
          onChange={(_, v) => setTab(v)}
          variant="fullWidth"
          sx={{ minHeight: 36, '& .MuiTab-root': { minHeight: 36, py: 0.5 } }}
        >
          <Tab label="Stats" />
          <Tab label="Commandes" />
          <Tab label="Sélection" />
          <Tab label="Village" />
          <Tab label="🎨 Calibration" sx={{ color: 'warning.main' }} />
        </Tabs>

        {!calibrating && (
          <Box sx={{ flex: 1, overflow: 'auto' }}>
            {tab === 0 && <StatsPanel />}
            {tab === 1 && <CommandesPanel />}
            {tab === 2 && <SelectionPanel />}
            {tab === 3 && <VillagePanel />}
          </Box>
        )}
      </Box>
    </Box>
  );
}
