// FSM de décision pour les habitants.
// Priorité : faim critique → repos → GatherSystem (tâches communautaires) → errance
//
// Transitions :
//   hunger < HUNGRY           → foraging (cherche nourriture pour lui-même)
//   energy < TIRED            → resting
//   idle + task (gather/return) → géré par GatherSystem, on ne touche pas
//   idle                      → wander

const HUNGRY      = 35;
const TIRED       = 22;
const REST_TICKS  = 6;
const EAT_DIST    = 1;  // distance de Manhattan pour manger

// Plantes qui nourrissent
const FOOD_TYPES = new Set(['baies', 'fruits', 'champignon', 'cactus', 'aloe', 'herbes', 'nenuphar']);

const IMPASSABLE = new Set(['eau', 'glace','montagne']);

function manhattan(ax, ay, bx, by) {
  return Math.abs(ax - bx) + Math.abs(ay - by);
}

function nearestFood(em, foodIds, px, py) {
  let best = null, bestD = Infinity;
  for (const fid of foodIds) {
    const fp = em.getComponent(fid, 'Position');
    if(fp==null) continue; // sécurité  
    const d  = manhattan(px, py, fp.x, fp.y);
    if (d < bestD) { bestD = d; best = { fid, pos: fp, d }; }
  }
  return best;
}

export default class DecisionSystem {
  update({ em, grid }) {
    // Collecte les sources de nourriture une seule fois par tick
    const foodIds = em.query('Position', 'Resource', 'Species').filter(id => {
      const sp  = em.getComponent(id, 'Species');
      const res = em.getComponent(id, 'Resource');
      return FOOD_TYPES.has(res.type);
    });

    for (const id of em.query('Position', 'Needs', 'State')) {
      const needs = em.getComponent(id, 'Needs');
      const state = em.getComponent(id, 'State');
      const pos   = em.getComponent(id, 'Position');
      const stats = em.getComponent(id, 'Stats');

      // ── En déplacement : ne pas interrompre sauf urgence extrême ──
      if (state.current === 'moving' && needs.hunger > 10) continue;

      // ── Tâche communautaire en cours (gather/return) → GatherSystem gère ──
      if (state.task?.action === 'gather' || state.task?.action === 'return') continue;

      // ── Repos en cours ─────────────────────────────────────────
      if (state.current === 'resting') {
        const timer = state.timer - 1;
        if (timer <= 0) {
          em.addComponent(id, 'Needs',  { ...needs, energy: Math.min(100, needs.energy + 35) });
          em.addComponent(id, 'State',  { ...state, current: 'idle', timer: 0 });
        } else {
          em.addComponent(id, 'State', { ...state, timer });
        }
        continue;
      }

      // ── FAIM critique ───────────────────────────────────────────
      if (needs.hunger < HUNGRY) {
        const food = nearestFood(em, foodIds, pos.x, pos.y);
        if (food) {
          if (food.d <= EAT_DIST) {
            // Mange
            em.destroyEntity(food.fid);
            em.addComponent(id, 'Needs', { ...needs, hunger: Math.min(100, needs.hunger + 45) });
            em.addComponent(id, 'State', { ...state, current: 'idle', target: null, task: null });
          } else {
            em.addComponent(id, 'State', {
              ...state, current: 'moving', target: food.pos, task: food.fid,
            });
          }
        }
        // Pas de nourriture → reste idle (affamé mais bloqué)
       // continue;  // ou pas
      }

      // ── FATIGUE ─────────────────────────────────────────────────
      if (needs.energy < TIRED) {
        em.addComponent(id, 'State', { ...state, current: 'resting', target: null, timer: REST_TICKS });
        continue;
      }

      // ── ERRANCE (idle) ──────────────────────────────────────────
      if (state.current === 'idle') {
        // Rayon de perception modulé par la stat
        const radius = 5 + Math.floor((stats?.perception ?? 50) / 12);
        const tx = Math.max(0, Math.min(grid.cols - 1,
          pos.x + Math.floor((Math.random() - 0.5) * radius * 2)));
        const ty = Math.max(0, Math.min(grid.rows - 1,
          pos.y + Math.floor((Math.random() - 0.5) * radius * 2)));
        const cell = grid.getCell(tx, ty);
        if (cell && !IMPASSABLE.has(cell.terrainType)) {
          em.addComponent(id, 'State', { ...state, current: 'moving', target: { x: tx, y: ty } });
        }
      }
    }
  }
}
